import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a worker that no longer exists. Requeue it for a fresh attempt;
// the attempt counter remains durable, so crash recovery also respects the three attempt cap.
db.exec(`BEGIN IMMEDIATE;
  UPDATE jobs SET status='queued', available_at=0, updated_at='${new Date().toISOString()}'
    WHERE status='running' AND attempts < 3;
  UPDATE jobs SET status='failed', error='transient failure', result_output=NULL,
    updated_at='${new Date().toISOString()}' WHERE status='running' AND attempts >= 3;
  COMMIT;`);

function heartbeat() { db.prepare(`INSERT INTO worker_heartbeat(id,at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET at=excluded.at`).run(Date.now()); }
async function processNext(): Promise<boolean> {
  const now = Date.now();
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare(`SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(now) as Record<string,unknown>|undefined;
    if (!row) { db.exec('COMMIT'); return false; }
    const attempt = Number(row.attempts)+1;
    const stamp = new Date().toISOString();
    db.prepare(`UPDATE jobs SET status='running', attempts=?, progress_completed=0, result_output=NULL, error=NULL, updated_at=? WHERE id=? AND status='queued'`).run(attempt,stamp,String(row.id));
    db.exec('COMMIT');
    const id=String(row.id), total=Number(row.steps);
    if (attempt <= Number(row.fail_attempts)) {
      await sleep(100);
      if (stopping) return true;
      if (attempt >= 3) {
        db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=? AND status='running'`).run(new Date().toISOString(),id);
      } else {
        db.prepare(`UPDATE jobs SET status='queued', available_at=?, updated_at=? WHERE id=? AND status='running'`).run(Date.now()+500,new Date().toISOString(),id);
      }
      return true;
    }
    for (let i=1;i<=total;i++) {
      await sleep(100);
      if (stopping) return true;
      db.prepare(`UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'`).run(i,new Date().toISOString(),id);
    }
    db.prepare(`UPDATE jobs SET status='completed', result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'`).run(String(row.input).toUpperCase(),new Date().toISOString(),id);
