  <h1>Job tracker</h1>
  <form data-testid="job-form">
    <label>Input <input data-testid="job-input" name="input" required maxlength="1000"></label>
    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" role="alert" aria-live="polite"></div>
  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list"></ul>
  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const alert = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    form.addEventListener('submit', async event => {
      event.preventDefault(); alert.textContent = '';
      const payload = {
        input: document.querySelector('[data-testid="job-input"]').value,
        steps: Number(document.querySelector('[data-testid="job-steps"]').value),
        failAttempts: Number(document.querySelector('[data-testid="job-fail-attempts"]').value)
      };
      try {
        const response = await fetch('/api/jobs', {method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify(payload)});
        const data = await response.json();
        if (!response.ok) {
          const fields = data.error?.fields || [];
          alert.textContent = fields.length ? fields.map(field => `${field.field}: ${field.message}`).join(' ') : data.error?.message || 'Submission failed.';
        } else { form.reset(); document.querySelector('[data-testid="job-steps"]').value = '5'; document.querySelector('[data-testid="job-fail-attempts"]').value = '0'; await refresh(); }
      } catch { alert.textContent = 'Unable to submit job. Please try again.'; }
    });
    async function refresh() {
      try {
        const response = await fetch('/api/jobs'); if (!response.ok) return;
        const {jobs} = await response.json();
        list.replaceChildren(...jobs.map(job => {
          const item = document.createElement('li'); item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
          const title = document.createElement('strong'); title.textContent = job.input;
          const status = document.createElement('span'); status.dataset.testid = 'job-status'; status.textContent = job.status;
          const progress = document.createElement('span'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
          const result = document.createElement('div'); result.dataset.testid = 'job-result'; result.textContent = job.result?.output ?? job.error ?? '';
          const meta = document.createElement('div'); meta.className = 'meta'; meta.append('Status: ',status,' · Progress: ',progress);
          item.append(title,meta,result); return item;
        }));
      } catch { /* retry on the next poll */ }
    }
    refresh(); setInterval(refresh, 500);
  </script>
</body>
</html>
